@page "/category/{CategoryName}"

<PageTitle>@CategoryName Recipes - RecipeShare</PageTitle>

<div class="container py-4">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">@CategoryName</li>
        </ol>
    </nav>

    <h1 class="mb-4">@CategoryName Recipes</h1>

    @if (Recipes.Count == 0)
    {
        <div class="alert alert-info">No recipes in this category yet. <a href="/submit">Be the first to submit one!</a></div>
    }
    else
    {
        <div class="row g-4">
            @foreach (var recipe in Recipes)
            {
                <div class="col-md-6">
                    <div class="card h-100 shadow-sm">
                        <div class="card-body">
                            <h4 class="card-title">@recipe.Title</h4>
                            <p class="text-warning mb-1">
                                @for (int i = 1; i <= 5; i++)
                                {
                                    <span>@(i <= (int)Math.Round(recipe.AverageRating) ? "★" : "☆")</span>
                                }
                                <small class="text-muted ms-1">(@recipe.AverageRating / 5, @recipe.RatingCount ratings)</small>
                            </p>
                            <a href="/recipe/@recipe.Id" class="btn btn-primary mt-2">View Recipe</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;
